
import { useState } from "react";
import gccData from "../data/gccData";
import ReactMarkdown from "react-markdown";

const API_BASE_URL = (
  import.meta.env.VITE_API_BASE_URL || "http://127.0.0.1:8000"
).replace(/\/+$/, "");

function normalizeMarkdown(text) {
  return text
    // Remove escaped Markdown formatting characters.
    .replace(/\\([*_`#])/g, "$1")

    // Repair escaped parentheses and square brackets in links.
    .replace(/\\\(/g, "(")
    .replace(/\\\)/g, ")")
    .replace(/\\\[/g, "[")
    .replace(/\\\]/g, "]")

    // Repair nested Markdown links generated by the AI.
    .replace(
      /\]\(\[(https?:\/\/[^\]]+)\]\(https?:\/\/[^)]+\)\)/g,
      "]($1)"
    );
}

function Assistant() {
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  async function handleSubmit(event) {
    event.preventDefault();

    if (!question.trim() || loading) return;

    setLoading(true);
    setError("");
    setAnswer("");

    try {
      const response = await fetch(`${API_BASE_URL}/api/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          question: question.trim(),
          records: gccData,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.detail || "The AI request failed. Please try again."
        );
      }

      setAnswer(data.answer);
    } catch (err) {
      setError(
        err.message ||
          "Unable to reach the AI backend. Check the API URL and backend status."
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="explorer-page">
      <p className="eyebrow">AI-POWERED RESEARCH</p>
      <h1>GCC Atlas Assistant</h1>

      <p className="subtitle">
        Ask questions about GCC records and explore the evidence
        available in your research dataset.
      </p>

      <form onSubmit={handleSubmit} className="company-card">
        <label htmlFor="assistant-question">
          What would you like to investigate?
        </label>

        <textarea
          id="assistant-question"
          rows={4}
          value={question}
          onChange={(event) => setQuestion(event.target.value)}
          placeholder="Example: What does our dataset say about Carlsberg in Gurugram?"
          required
        />

        <button type="submit" disabled={loading || !question.trim()}>
          {loading ? "Researching..." : "Ask GCC Atlas"}
        </button>
      </form>

      {loading && (
        <p className="results-count">
          Gemini is reviewing your research records...
        </p>
      )}

      {error && (
        <div className="company-card" role="alert">
          <h2>Unable to get an answer</h2>
          <p>{error}</p>
        </div>
      )}

      {answer && (
        <section className="company-card" aria-live="polite">
          <p className="eyebrow">AI RESPONSE</p>
          <h2>Research findings</h2>

          <div className="assistant-answer">
            <ReactMarkdown
              components={{
                a: ({ href, children, ...props }) => (
                  <a
                    href={href}
                    target="_blank"
                    rel="noopener noreferrer"
                    {...props}
                  >
                    {children}
                  </a>
                ),
              }}
            >
              {normalizeMarkdown(answer)}
            </ReactMarkdown>
          </div>
        </section>
      )}

      <p className="subtitle">
        AI responses may contain errors. Verify important claims
        against the original source announcements.
      </p>
    </div>
  );
}

export default Assistant;
